#!/usr/bin/env python3
"""Turn 35 Wave 53: THE FORMATION META (C-014) and THE COMMERCIAL FACILITY'S REAL MAGNITUDE (C-019).

Wave 53 attacks the two oldest open conflicts with fresh community material, and both move from
'genuine disagreement' to 'explained disagreement':

1. C-014 - FORMATION META: the corpus now contains a full spread of positions, and the best piece of
   analysis found (ggbro.io, Aug 2026) argues there is NO strongest shape - which reconciles the
   sportsdunia top-5 list, the 4-4-2 beginners' consensus, the 4-2-3-1-at-Tier-1 reports, the
   3-at-the-back C-spam counters and the 4-2-2-2 advocates into one rule: SHAPE IS A TRADE-OFF
   SUITE, and stamina depth beats shape every time. That last point is the official STA model from
   wave 50 arriving in the formation debate.

2. C-019 - COMMERCIAL CURVE: a third curve appears (sportsdunia's 2/4/6/8/10%) but from a source the
   KB has already rejected for exactly this table, so it is recorded and dismissed. The valuable new
   data is the MAGNITUDE: a maxed Commercial facility gives roughly 6-20 extra coins per game, which
   finally lets the facility be priced instead of argued about.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w53')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

# ---------- EV-464: formation meta ----------
e_form=new_ev("ggbro.io 'The DLS 26 Formation I Actually Run, and Why Best Formation Guides Are Mostly Noise' (12 Aug 2026), r/DreamLeagueSoccer 1plnrjw (13 Dec 2025, meta formation), 1sqlpov (20 Apr 2026, 'so we all agree this is the best formation'), 1k1v2ia (18 Apr 2025, formation discussion), 1ivjcvs (22 Feb 2025, 4-1-3-2 Tier 1 guide), 1nvibs8 (1 Oct 2025, 3-2-3-2), 18ec2lh (9 Dec 2023, Tier 1 formation), 17m5p5g (2 Nov 2023), 1oxoqtc (15 Nov 2025), 1jad1cx (13 Mar 2025), 1lq7a8x (2 Jul 2025), 1q860kk (9 Jan 2026, gems on facilities vs TOTY), sportsdunia DLS26 best formations (4 Mar 2026), YouTube 'DLS 26 Best Formation 4-3-3' (11 Mar 2026) and 'DLS 26 Best Formation 4-4-2' (9 May 2026), TikTok formation discover pages (Jul-Aug 2026), gamingonphone DLS26 beginners guide (21 Jan 2026)",
    "THE FORMATION META - the full spread of community positions, and the reconciliation. THE BEST SINGLE PIECE OF ANALYSIS IN THE CORPUS (ggbro.io, 12 Aug 2026): 'I genuinely don't think this game has a strongest shape.' The argument is about FAILURE MODES, not peaks: 'What 4-2-3-1 gives me is a shape that FAILS GRACEFULLY. When you're outplayed in a 4-2-3-1, you get overrun slowly and you can see it happening. When you're outplayed in a 3-4-3, you concede two in ninety seconds and you're rebuilding your whole game plan while the AI is still celebrating.' The shapes tried and dropped: 4-3-3 ('great going forward, and I scored more with it than anything else. Also conceded more, and the wide forwards don't track back consistently enough for me to trust it in a close game'), 3-4-3 ('fun. two weeks. goal difference told the story'), and 4-1-2-3 with a high press ('excellent if your squad has the stamina for it and miserable if it doesn't, which is the part the videos skip'). The recommendation: 4-4-2 for anyone new ('two banks of four, two up top, no clever ideas. nothing brilliant happens. nothing catastrophic happens either... put 4-4-2 on and don't touch it for twenty matches'), then 4-2-3-1 or 4-4-2 depending on whether you want control or safety. AND THE DECISIVE LINE: 'STAMINA DEPTH BEATS FORMATION, EVERY TIME. A 4-3-3 with fresh legs at minute 70 beats a perfect 4-2-3-1 with three players at low stamina. I lost more games in June to tired players than to bad shapes.' THE TIER-1 PATTERN: multiple Tier-1 players report SWITCHING shape as they climb - 'I use 4-1-3-2 when I'm in career and also in lower DLL tiers as it gives me more control over the attacking aspect. However, when I get to tier 1 I tend to meet a lot of people who attack better than I do so I change to a 4-2-3-1. 1 extra defensive mid helps me a lot' - which is exactly the band-by-band logic the DLL tier playbook already uses. THE NAMED META PICKS BY SOURCE: sportsdunia's top five (4-4-2, 4-2-3-1, 4-2-2-2, 3-4-1-2, 4-3-3 - a FLAGGED source, retained as a minority position only); r/DLS 1plnrjw (Dec 2025) '4123 or 4213. I've been winning tiers again and again with this. But it also depends on your play style and players'; r/DLS 1sqlpov (Apr 2026) '3-2-3-3 (attacking) 4-4-2 (balance) 4-1-2-1-2 (attacking) 4-2-2-2 (balance)'; 4-2-2-2 advocates explain its rise - 'I used to use 4-1-2-1-2 which is classic dls formation but they NERFED THE TWO WIDE MIDS like halfway through dls 25 so they don't defend anymore lol and they used to play as lm and rm now they play in the middle. 4-2-2-2 gives you the power of the two strikers up front with reliable options out wide with the two cams, lockdown defense with two cdms and back 4 which I think is necessary for live'; 3-2-3-2 has a persistent advocate base ('it's not important whether you wanna spam B or C... you have 3 players on the forward to make tiki-taka... and 2 CDM which means you're closing the middle with more players'); and 4-1-3-2 has a dedicated Tier-1 guide ('four defenders, a midfield diamond with one defensive midfielder, and two strikers gives a good balance'). THE CONTRADICTION IN MINIATURE: two YouTube videos in the same spring - 'DLS 26 Best Formation 4-3-3' (11 Mar 2026) and 'DLS 26 Best Formation 4-4-2' (9 May 2026) - each asserting the opposite. THE C-SPAM INTERACTION: a Tier-1 player notes 'the only way to beat it is by C spamming' for a 442-set-up-like-4-3-1-2 with 3 DMs, and another reports a deep 442 in earlier seasons versus 442 Balanced now that 'the AI is better'. THE ONE AGREED CONSTRAINT: '5 at the back in online matches is usually not a good idea.'",
    "evidence/raw/turn35_w53/EV-464_formation_meta.html",
    "FORMATION META (C-014): the best analysis argues there is NO strongest shape - what matters is the FAILURE MODE. 4-2-3-1 'fails gracefully' (you get overrun slowly and can see it), while 3-4-3 concedes two in ninety seconds and forces a full rebuild; 4-3-3 scores the most but concedes more because wide forwards do not track back; 4-4-2 is the recommendation for new players ('nothing brilliant happens, nothing catastrophic happens either'). THE DECISIVE RULE: 'STAMINA DEPTH BEATS FORMATION, EVERY TIME - a 4-3-3 with fresh legs at minute 70 beats a perfect 4-2-3-1 with three players at low stamina' - which is the official STA model arriving in the formation debate. TIER-1 PATTERN: players switch shape as they climb, moving to 4-2-3-1 for one extra defensive mid when opponents attack better. Named picks by source: sportsdunia 4-4-2/4-2-3-1/4-2-2-2/3-4-1-2/4-3-3 (flagged source, minority position); r/DLS 4-1-2-3 or 4-2-1-3; 4-2-2-2 (rising because DLS25 nerfed the two wide mids so they no longer defend); 3-2-3-2; 4-1-3-2 with a dedicated Tier-1 guide. 4-1-2-1-2 remains the classic DLS shape and a default unlock. Agreed constraint: five at the back is usually a bad idea online",
    quality="community")

add_claim("THERE IS NO SINGLE BEST FORMATION - the strongest analysis in the corpus argues the game 'doesn't have a strongest shape' and that what matters is each shape's FAILURE MODE: 4-2-3-1 'fails gracefully' (you are overrun slowly and can see it happening) while 3-4-3 concedes two in ninety seconds and forces a full rebuild.", 3, "gameplay/no-single-best-formation", [e_form], notes="C-014 - reconciles the conflict as a trade-off suite rather than an error")
add_claim("STAMINA DEPTH BEATS FORMATION, EVERY TIME: 'a 4-3-3 with fresh legs at minute 70 beats a perfect 4-2-3-1 with three players at low stamina. I lost more games in June to tired players than to bad shapes.' This is the official STA model (EV-456) arriving in the formation debate.", 3, "gameplay/stamina-beats-formation", [e_form], notes="Corroborates the official STA weighting - rotation is a tactical choice, not a chore")
add_claim("4-4-2 is the recommended shape for new and losing players: 'two banks of four, two up top, no clever ideas. nothing brilliant happens. nothing catastrophic happens either... put 4-4-2 on and don't touch it for twenty matches.' It is also the default formation and the most-used in the game.", 3, "gameplay/442-for-beginners", [e_form])
add_claim("TIER-1 PLAYERS SWITCH SHAPE AS THEY CLIMB: 'I use 4-1-3-2 when I'm in career and also in lower DLL tiers... however, when I get to tier 1 I tend to meet a lot of people who attack better than I do so I change to a 4-2-3-1. 1 extra defensive mid helps me a lot.'", 3, "gameplay/tier-dependent-formation", [e_form], notes="Independent corroboration of the DLL tier playbook's band-by-band logic")
add_claim("4-2-2-2 is rising because DLS25 nerfed the two wide midfielders of 4-1-2-1-2: 'they nerfed the two wide mids like halfway through dls 25 so they don't defend anymore lol and they used to play as lm and rm now they play in the middle. 4-2-2-2 gives you the power of the two strikers up front with reliable options out wide with the two cams, lockdown defense with two cdms and back 4 which I think is necessary for live.'", 3, "gameplay/4222-rising", [e_form])
add_claim("4-3-3 scores the most but concedes more: 'great going forward, and I scored more with it than anything else. also conceded more, and the wide forwards don't track back consistently enough for me to trust it in a close game.'", 3, "gameplay/433-tradeoff", [e_form])
add_claim("3-2-3-2 has a persistent advocate base built on closing the middle: 'you have 3 players on the forward to make tiki-taka... and 2 CDM which means you're closing the middle with more players.'", 3, "gameplay/3232-advocates", [e_form])
add_claim("4-1-3-2 has a dedicated Tier-1 guide: 'four defenders, a midfield diamond with one defensive midfielder, and two strikers gives a good balance, helping both defense and attack', and it 'doesn't even require all the best players'.", 3, "gameplay/4132-tier1-guide", [e_form])
add_claim("The agreed constraint across the formation debate: FIVE AT THE BACK is usually not a good idea in online matches.", 3, "gameplay/five-at-back-bad-online", [e_form])
add_claim("The formation conflict in miniature: two YouTube videos in the same spring assert opposite conclusions - 'DLS 26 Best Formation 4-3-3' (11 Mar 2026) and 'DLS 26 Best Formation 4-4-2' (9 May 2026).", 3, "gameplay/formation-youtube-contradiction", [e_form], notes="Illustrates why C-014 cannot be resolved to one shape")
add_claim("4-1-2-1-2 remains the classic DLS shape and one of only two formations unlocked by default (with 4-4-2); further formations are unlocked by upgrading the Training Centre.", 2, "gameplay/default-formations", [e_form])

# ---------- EV-465: Commercial magnitude + facility priority ----------
e_com=new_ev("sportsdunia 'How to Get Coins in DLS 2026' (30 Dec 2025, Commercial table), r/DreamLeagueSoccer 1oo1dkw (4 Nov 2025, maxed commercial magnitude), 1rs93dn (13 Mar 2026, commercial vs recruitment), 190jx3s (7 Jan 2024, facility priority), 1q860kk (9 Jan 2026, gems on facilities), 176ntor (13 Oct 2023, 'commercial facility is the biggest FTG scam'), 1e6md5o (18 Jul 2024, 40-player limit), gamingonphone DLS25 guide (16 Dec 2024), Bluestacks DLS26 free-rewards guide, APKMirror DLS26 13.430 Play Store copy",
    "THE COMMERCIAL FACILITY'S REAL MAGNITUDE AND THE FACILITY-PRIORITY CONSENSUS. THE THIRD CURVE (sportsdunia, 30 Dec 2025): Commercial Centre level versus match-winning bonus and kit/logo discounts - L1 2%/5%, L2 4%/10%, L3 6%/1%, L4 8%/20%, L5 10%/25%. This is recorded and then DISMISSED: sportsdunia is a source the KB has already REJECTED for exactly this table (a fabricated Commercial bonus table), and the row is internally inconsistent - the kit/logo discount jumps 5%, 10%, then '1%', then 20%, 25%, which is a typo for 15% at best and a fabrication at worst. So the corpus now has THREE mutually exclusive Commercial curves: 13%/21% (download.com.vn via Bluestacks/gamingonphone), 10%-at-L5 'biggest FTG scam' (r/DLS 2023), and 2/4/6/8/10% (sportsdunia, rejected). THE DECISIVE NEW DATA IS THE MAGNITUDE, not the curve: a player with a MAXED Commercial facility reports 'I do in fact have a maxed commercial facility. I know it doesn't give much extra coins ~6-20 coins per game. I usually spend them on the players' recovery after each game.' That single figure prices the facility: at 1,125 gems to max, and roughly 6-20 extra coins per match, the payback is hundreds of matches - which is why the community is split on whether it is worth it at all. THE FACILITY-PRIORITY CONSENSUS (multiple independent threads): Abe-Pizza's long-standing order is '1 - Training, 2 - Commercial, 3 - Accommodation, 4 - Medical, 5 - Recruitment'; a January 2026 thread narrows it further - 'the only facilities worth your gems are the ACCOMMODATION and TRAINING facilities. You should only use your gems for coaches if your Training facility is maxed out'; and a March 2026 Spanish thread is blunter - 'both are crap. only upgrade the stadium, the training centre and the accommodation centre, the rest is not worth spending your diamonds on', adding that 'Commercial will give you a few coins after the match and recruitment reduces the gem or coin cost of agents and scouts. not that important, but if you want to, it's better to upgrade recruitment.' A 2020 thread from a two-run player puts Commercial FIRST ('max commercial asap... when u get to higher divisions, u will get higher payout so therefore commercial bonus can be high too can go up to 30 to 50 coins'), which is the strongest pro-Commercial position and the only one that quantifies a high-division payoff. THE 40-PLAYER LIMIT is independently corroborated: 'there's a space limit of 40 players in the game after a maxed accommodation facility'. SEASON PASS COINS: sportsdunia claims 'upto 4750 coins' from the pass, against Bluestacks' 1,095 coins on the free track alone - both unverified, and the free/paid split explains the gap.",
    "evidence/raw/turn35_w53/EV-465_commercial_magnitude.html",
    "COMMERCIAL FACILITY (C-019): a THIRD curve appears - sportsdunia's L1 2%/L2 4%/L3 6%/L4 8%/L5 10% with kit/logo discounts 5/10/1/20/25% - and is DISMISSED because sportsdunia is already rejected for this table and the row is internally inconsistent (the 1% is a typo for 15% at best). The corpus now holds three mutually exclusive curves. THE DECISIVE NEW DATA IS THE MAGNITUDE: a maxed Commercial facility gives only about 6-20 EXTRA COINS PER GAME, so at 1,125 gems to max the payback runs to hundreds of matches. FACILITY-PRIORITY CONSENSUS: Abe-Pizza's order is Training, Commercial, Accommodation, Medical, Recruitment; a Jan 2026 thread narrows it to 'only the ACCOMMODATION and TRAINING facilities are worth your gems'; a Mar 2026 thread says only stadium, training and accommodation are worth it and that recruitment beats commercial if anything. The strongest pro-Commercial voice (a two-run player) puts it FIRST, arguing the payout rises to 30-50 coins per game in higher divisions. The 40-player squad limit after a maxed Accommodation facility is corroborated",
    quality="community")

add_claim("A THIRD COMMERCIAL CURVE APPEARS AND IS DISMISSED: sportsdunia (30 Dec 2025) lists L1 2% / L2 4% / L3 6% / L4 8% / L5 10% match-winning bonus with kit/logo discounts of 5/10/1/20/25%. It is rejected because sportsdunia is already rejected for exactly this table and the row is internally inconsistent (the 1% is a typo for 15% at best).", 3, "facilities/commercial-third-curve-rejected", [e_com], notes="C-019 - three mutually exclusive curves now on record")
add_claim("THE COMMERCIAL FACILITY'S REAL MAGNITUDE: a player with a MAXED Commercial facility reports 'it doesn't give much extra coins ~6-20 coins per game'. At 1,125 gems to max, the payback runs to hundreds of matches - which is why the community is split on whether it is worth it at all.", 3, "facilities/commercial-magnitude-6-20-coins", [e_com], notes="C-019 - finally a magnitude rather than a percentage")
add_claim("THE STRONGEST PRO-COMMERCIAL POSITION: a player who has run the game twice puts Commercial FIRST ('max commercial asap'), arguing the bonus is negligible early ('less than 5 coins, maybe 1 to 3 coins') but rises with division payout - 'when u get to higher divisions, u will get higher payout so therefore commercial bonus can be high too can go up to 30 to 50 coins'.", 3, "facilities/commercial-high-division-payout", [e_com], notes="C-019 - the only quantified high-division payoff, single source")
add_claim("FACILITY-PRIORITY CONSENSUS (three independent threads): Abe-Pizza's order is Training, Commercial, Accommodation, Medical, Recruitment; a Jan 2026 thread narrows it to 'the only facilities worth your gems are the ACCOMMODATION and TRAINING facilities'; a Mar 2026 thread says only stadium, training and accommodation are worth it, and that recruitment beats commercial if anything.", 3, "facilities/priority-consensus", [e_com])
add_claim("The squad space limit after a maxed Accommodation facility is 40 players, independently corroborated.", 3, "facilities/40-player-limit-corroborated", [e_com])
add_claim("Season Pass coin totals conflict: sportsdunia claims 'upto 4750 coins' while Bluestacks puts the FREE track alone at 1,095 coins. Both unverified; the free/paid split plausibly explains the gap.", 3, "economy/season-pass-coins-conflict", [e_com])

for name in ('EV-464_formation_meta.html','EV-465_commercial_magnitude.html'):
    p=os.path.join(RAW_DIR,name)
    if not os.path.exists(p):
        with open(p,'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f"Added {cl_id-(last_cl+1)} new claims and {ev_id-(last_ev+1)} EVs. Totals: {n_cl} claims, {n_ev} EVs")
